//! 🧪️ A real UTF-8 probe preserves work even though its original output never receives a byte.
use super::*;
#[test]fn original_wire_actual_work_survives_allocation_probe_failure_denial_and_paid_close(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let source:Vec<u8>=serde_json::from_value(f["invalidUtf8"].clone()).unwrap();assert!(std::str::from_utf8(&source).is_err());assert!(serde_json::from_slice::<String>(&[34,source[0],34]).is_err());let stock=&f["stock"];let mut left=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:stock["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let mut fuel=stock["fuel"].as_u64().unwrap();let mut cursor=RetainedWireFieldDecode::new(&source,true);let address=source.as_ptr();
 let grant=|left:RetainedCloneGrant|RetainedCloneGrant{maximum_items:left.maximum_items.min(1),maximum_copy_bytes:left.maximum_copy_bytes.min(4096),maximum_capacity_bytes:left.maximum_capacity_bytes.min(65536),maximum_release_bytes:left.maximum_release_bytes.min(65536),maximum_depth:left.maximum_depth};let debit=|left:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,w:u64|{assert!(p.fits(*left));left.maximum_items-=p.copied_items;left.maximum_copy_bytes-=p.copied_bytes;left.maximum_capacity_bytes-=p.retained_capacity_bytes;left.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(w).unwrap();};
 let g=grant(left);assert_eq!(cursor.advance(&source,RetainedCloneGrant{maximum_items:0,..g}).unwrap(),RetainedWireFieldStep::Blocked);assert_eq!(cursor.last_turn_work(),0);cursor.advance(&source,g).unwrap();let w=cursor.last_turn_work();let(_,p)=cursor.take_receipt().unwrap();assert_eq!(w,1);debit(&mut left,&mut fuel,p,w);
 let fault=cursor.advance(&source,grant(left)).unwrap_err();let w=cursor.last_turn_work();assert_eq!(w,1);assert_eq!(fault.retained_progress().copied_items,0);assert_eq!(fault.kind,ValueRefusalKind::InvalidValue);debit(&mut left,&mut fuel,fault.retained_progress(),w);assert_eq!(source.as_ptr(),address);assert!(cursor.output.as_ref().unwrap().is_empty());
 cursor.cancel();for _ in 0..10000{if cursor.terminal_is_empty(){break}cursor.close_step(grant(left)).unwrap();let w=cursor.last_turn_work();let p=cursor.take_receipt().map_or(Default::default(),|(_,p)|p);debit(&mut left,&mut fuel,p,w);}assert!(cursor.terminal_is_empty());assert_eq!(cursor.close_step(Default::default()).unwrap(),RetainedWireFieldStep::Closed);assert_eq!(cursor.last_turn_work(),0);
}
